function makeQuestion(key: string, sectionCode: string, groupKey: string, item: Passage['questions'][number], level: 'B1' | 'B2'): DatasetQuestion {
  return {
    key, sectionCode, groupKey, questionTypeCode: item.type, topicCodes: [item.topic], content: item.prompt, level,
    difficulty: level === 'B1' ? 'MEDIUM' : 'HARD', hint1: 'Locate the relevant sentence or paragraph, then eliminate options that are not supported.', explanation: item.explanation,
    options: [item.answer, ...item.distractors].map((content, position) => ({ key: String.fromCharCode(65 + position), content, isCorrect: position === 0, explanation: position === 0 ? item.explanation : 'This option is not supported by the passage.' })),
  };
}

function makeDataset(key: string, examTypeCode: 'HCMUS_MASTER_ENTRANCE' | 'VSTEP', subset: Passage[]): ExamDataset {
  const groups: DatasetGroup[] = subset.map((passage) => ({ key: passage.key, kind: 'PASSAGE', title: passage.title, stimulus: passage.text, provenanceNotes: 'Synthetic passage authored for practice; not an official or reconstructed exam text.' }));
  const questions = subset.flatMap((passage, passageIndex) => passage.questions.map((item, questionIndex) => {
    // ULIS explicitly names five VSTEP reading skills. HCMUS's cited notice does
    // not publish a reading taxonomy, so its pool uses the generic type only.
    const normalizedItem = examTypeCode === 'HCMUS_MASTER_ENTRANCE' ? { ...item, type: 'READING_COMPREHENSION' } : item;
    return makeQuestion(`${key}-${String(passageIndex + 1).padStart(2, '0')}-${String(questionIndex + 1).padStart(2, '0')}`, 'READING', passage.key, normalizedItem, passage.level);
  }));
  const vstepSource = 'https://vstep.vnu.edu.vn/test-format/';
  const hcmusSource = 'https://sdh.hcmus.edu.vn/2026/05/15/thong-bao-ve-viec-nhan-giay-bao-thi-va-lich-thi-noi-quy-thi-tuyen-sinh-sau-dai-hoc-nam-2026-dot-1-2/';
  return {
    key, examTypeCode, title: `${examTypeCode === 'VSTEP' ? 'VSTEP' : 'HCMUS Master Entrance'} Synthetic Reading Practice`,
    source: 'Synthetic reading content authored after reviewing the cited official specification; not an official exam paper.', sourceType: 'SYNTHETIC_MOCK', sourceReference: examTypeCode === 'VSTEP' ? vstepSource : hcmusSource, sourceUrl: examTypeCode === 'VSTEP' ? vstepSource : hcmusSource,
    provenanceNotes: examTypeCode === 'VSTEP'
      ? 'ULIS-VNU test-format specification was read for structure and stated skills: 60 minutes; four passages; 40 MCQs; ten questions per passage; total reading text 1900-2500 words; levels 3-5/B1-C1; detail, main idea, attitude, inference, and vocabulary in context. This dataset contains newly authored synthetic passages and questions only; it is not an official or reconstructed sample.'
      : 'The HCMUS 2026 notice was read for the verified four-skill English examination and maximum 120-minute Reading-Writing-Listening block. It does not publish detailed Reading counts or taxonomy, so this is a general synthetic reading practice pool and makes no claim about an official HCMUS Reading format.',
    detectedLevel: 'B1_B2', blueprintKey: examTypeCode === 'VSTEP' ? 'VSTEP_3_5' : 'HCMUS_MASTER',
    sections: [{ code: 'READING', name: 'Reading passages', position: 1, questionCount: questions.length, passageCount: groups.length, durationMinutes: examTypeCode === 'VSTEP' ? 60 : undefined }], groups, questions,
  };
}

// VSTEP uses four passage groups and ten questions per group, matching ULIS's published shape.
// HCMUS remains a separate general practice pool because the cited notice does not specify Reading counts.
export const readingExpansionDatasets = [
  makeDataset('vstep-reading-grounded', 'VSTEP', passages.slice(0, 4)),
  makeDataset('hcmus-reading-practice', 'HCMUS_MASTER_ENTRANCE', passages.slice(4)),
];
